class Solution {
public:
    bool isValidPalindrome(std::string s, int k) {
        int n = s.size();
        std::string rev = s;
        std::reverse(rev.begin(), rev.end());
        std::vector<int> dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            std::vector<int> nxt(n + 1, 0);
            for (int j = 1; j <= n; ++j) {
                if (s[i - 1] == rev[j - 1]) {
                    nxt[j] = dp[j - 1] + 1;
                } else {
                    nxt[j] = std::max(dp[j], nxt[j - 1]);
                }
            }
            dp = std::move(nxt);
        }
        return n - dp[n] <= k;
    }
};

class Solution {
    public boolean isValidPalindrome(String s, int k) {
        int n = s.length();
        String rev = new StringBuilder(s).reverse().toString();
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int[] nxt = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == rev.charAt(j - 1)) {
                    nxt[j] = dp[j - 1] + 1;
                } else {
                    nxt[j] = Math.max(dp[j], nxt[j - 1]);
                }
            }
            dp = nxt;
        }
        return n - dp[n] <= k;
    }
}

var isValidPalindrome = function(s, k) {
    const n = s.length;
    const rev = s.split('').reverse().join('');
    let dp = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        const nxt = new Array(n + 1).fill(0);
        for (let j = 1; j <= n; j++) {
            if (s[i - 1] === rev[j - 1]) {
                nxt[j] = dp[j - 1] + 1;
            } else {
                nxt[j] = Math.max(dp[j], nxt[j - 1]);
            }
        }
        dp = nxt;
    }
    return n - dp[n] <= k;
};
